export const DEFAULT_ASSETS={"schema_version": 1, "characters": [{"asset_id": "knight", "name": "蓝披风剑士", "type": "character", "renderer": "spine_builtin", "rig": "knight", "animations": {"idle": "idle", "attack": "attack"}}, {"asset_id": "moon_mage", "name": "银发法师", "type": "character", "renderer": "spine_builtin", "rig": "moon-mage", "animations": {"idle": "idle", "attack": "attack"}}, {"asset_id": "sun_mage", "name": "红帽法师", "type": "character", "renderer": "spine_builtin", "rig": "sun-mage", "animations": {"idle": "idle", "attack": "attack"}}, {"asset_id": "captain", "name": "红发船长", "type": "character", "renderer": "spine_builtin", "rig": "captain", "animations": {"idle": "idle", "attack": "attack"}}, {"asset_id": "penguin", "name": "皇冠企鹅", "type": "character", "renderer": "spine_builtin", "rig": "penguin", "animations": {"idle": "idle", "attack": "attack"}}, {"asset_id": "dragon", "name": "赤翼幼龙", "type": "character", "renderer": "spine_builtin", "rig": "dragon", "animations": {"idle": "idle", "attack": "attack"}}], "effects": [{"asset_id": "pixel_slash", "name": "刀光命中·粒子", "type": "effect", "renderer": "particles", "angle_deg": -45, "particle_count": 14, "preset": "slash", "color": "#fff2ab", "duration_ms": 350}, {"asset_id": "pixel_burst", "name": "像素爆闪", "type": "effect", "renderer": "css", "preset": "burst", "color": "#7ee8ff", "duration_ms": 350}]};
DEFAULT_ASSETS.effects.push({"asset_id":"pixel_fireball_hit","name":"小火球命中·粒子","type":"effect","renderer":"particles","preset":"fireball","color":"#ff9b32","duration_ms":480,"particle_count":18});
export const TEMPLE_SWORDSMAN={asset_id:'temple_swordsman',name:'教会卫队剑士',type:'character',renderer:'sequence_builtin',rig:'temple_swordsman',animations:{idle:'idle',attack:'attack'}};
export const assetLibrary=data=>{const lib=data.art_assets||DEFAULT_ASSETS;return {...lib,characters:lib.characters.some(a=>a.asset_id==='temple_swordsman')?lib.characters:[...lib.characters,structuredClone(TEMPLE_SWORDSMAN)]};};
export function artIssues(data){const lib=assetLibrary(data),errors=[];if(!lib||lib.schema_version!==1||!Array.isArray(lib.characters)||!Array.isArray(lib.effects))return ['美术资产库结构错误'];if([...lib.characters,...lib.effects].some(a=>!a||typeof a!=='object'))return ['美术资产定义必须是对象'];const ids=new Set();for(const a of [...lib.characters,...lib.effects]){if(!/^[a-z][a-z0-9_]*$/.test(a.asset_id)||ids.has(a.asset_id))errors.push('美术资产ID非法或重复');ids.add(a.asset_id);if(!a.name)errors.push('资产缺少名称');}for(const a of lib.characters){if(a.type!=='character'||!((a.renderer==='spine_builtin'&&DEFAULT_ASSETS.characters.some(x=>x.rig===a.rig))||(a.renderer==='sequence_builtin'&&a.rig==='temple_swordsman'&&a.animations?.idle==='idle'&&a.animations?.attack==='attack'))||!['idle','attack','hit','enter','exit','defeat'].includes(a.animations?.idle)||!['idle','attack','hit','enter','exit','defeat'].includes(a.animations?.attack))errors.push('角色必须指定支持的骨骼与待机/攻击动作');}for(const a of lib.effects)if(a.type!=='effect'||!['css','particles'].includes(a.renderer)||a.renderer==='particles'&&!['slash','fireball'].includes(a.preset)||a.preset==='fireball'&&a.renderer!=='particles'||a.angle_deg!==undefined&&(!Number.isFinite(a.angle_deg)||Math.abs(a.angle_deg)>180)||a.particle_count!==undefined&&(!Number.isInteger(a.particle_count)||a.particle_count<0||a.particle_count>48)||!['slash','burst','fireball'].includes(a.preset)||!/^#[0-9a-f]{6}$/i.test(a.color)||!Number.isInteger(a.duration_ms)||a.duration_ms<100||a.duration_ms>3000)errors.push('特效参数非法');for(const c of data.cards||[]){if(c.art_id&&!lib.characters.some(a=>a.asset_id===c.art_id))errors.push(c.name+'引用角色不存在');if(c.attack_effect_id&&!lib.effects.some(a=>a.asset_id===c.attack_effect_id))errors.push(c.name+'引用攻击特效不存在');}return errors;}
export function resolveArt(data,card){const lib=assetLibrary(data);return {character:structuredClone(lib.characters.find(a=>a.asset_id===card.art_id)||null),attackEffect:structuredClone(lib.effects.find(a=>a.asset_id===card.attack_effect_id)||null)};}
